/* @lc app=leetcode id=2672 lang=kotlin */ class Solution { fun colorTheArray(n: Int, queries: Array<IntArray>): IntArray = IntArray(n).let { a -> queries.fold(0 to ArrayList<Int>()) { (cnt, res), (i, c) -> (cnt - (if (a[i] != 0 && i > 0 && a[i - 1] == a[i]) 1 else 0) - (if (a[i] != 0 && i < n - 1 && a[i + 1] == a[i]) 1 else 0)).let { c1 -> a.also { it[i] = c }.let { (c1 + (if (i > 0 && a[i - 1] == c) 1 else 0) + (if (i < n - 1 && a[i + 1] == c) 1 else 0)).let { c2 -> c2 to res.also { it.add(c2) } } } } }.second.toIntArray() } }